// Why: generated code must be readable by people and agents, and a
// diagnostic in it must name a file they can open, yet the compiler must
// never read that file back as source.
//
// What: the per-target gen/ view of a module (genViews, genViewBytes,
// genViewOwned, writeGenView) and E0904 for a hand-edited view (e0904). The
// view is written only when changed and is excluded from source hashing.
//
// How: the view of a module is <module dir>/gen/<target>/gen.mk, the virtual
// path gen gives the generated file in Sources, so a diagnostic that cites
// generated text names the file a person or agent can open. Its text is the
// generated file's, byte for byte (so every line and column a diagnostic
// cites is the view's), followed by one trailer line holding the hash of
// that text. A view whose text no longer matches its own trailer was edited
// by hand: E0904, and the file is left as it is. A view that matches its
// trailer is mk's, and is rewritten when the output changed, removed when
// the module has no gen line left.

package driver

import (
	"os"
	"path/filepath"
	"strings"

	"mk/internal/diag"
	"mk/internal/source"
)

// genViewTrailer starts the view's last line; the text hash follows it.
const genViewTrailer = "// mk gen view "

// genViewHash is the hash a view's trailer holds: of the generated text.
func genViewHash(text string) source.Hash {
	h := source.NewHasher("mk.genview.v1")
	h.String(text)
	return h.Sum()
}

// genViewBytes is the whole view of text for target: the text, then the
// trailer line.
func genViewBytes(text, target string) []byte {
	var b strings.Builder
	b.WriteString(text)
	if text != "" && !strings.HasSuffix(text, "\n") {
		b.WriteByte('\n')
	}
	b.WriteString(genViewTrailer)
	b.WriteString(genViewHash(text).String())
	b.WriteString(" generated by mk from this module's gen lines for ")
	b.WriteString(target)
	b.WriteString("; edit them, not this file (E0904)\n")
	return []byte(b.String())
}

// genViewOwned reports whether data is a view mk wrote and nobody edited:
// its last line is a trailer whose hash is that of the text before it.
func genViewOwned(data []byte) bool {
	s := string(data)
	// mk writes LF only (generated text is LF-normalized), so a CR is an
	// edit, even one an editor made by converting line endings.
	if !strings.HasSuffix(s, "\n") || strings.ContainsRune(s, '\r') {
		return false
	}
	body := s[:len(s)-1]
	i := strings.LastIndexByte(body, '\n') + 1
	last := body[i:]
	if !strings.HasPrefix(last, genViewTrailer) {
		return false
	}
	hex, _, _ := strings.Cut(last[len(genViewTrailer):], " ")
	// The text is what precedes the trailer line, less the newline
	// genViewBytes adds after a text that does not end in one.
	text := body[:i]
	if hex == genViewHash(text).String() {
		return true
	}
	return strings.HasSuffix(text, "\n") && hex == genViewHash(text[:len(text)-1]).String()
}

// genViews writes, checks and removes the gen/ views of the package's
// modules (Config.GenView), after the pipeline: every module whose gen
// lines produced output gets its view; a module with no gen line left loses a view
// that is still mk's. Only a package or directory root on disk has views:
// never std (embedded, and std/ is embedded with go:embed *), a single
// file (its directory is not its module's own), a corpus unit or the test
// runner (memory trees). A view that cannot be written changes nothing the
// compiler decides, so a write failure is not a diagnostic.
func (s *Session) genViews() []*diag.Diagnostic {
	if !s.cfg.GenView || s.pkgB == nil || s.root.kind == rootFile {
		return nil
	}
	var out []*diag.Diagnostic
	target := s.cfg.Target.Name
	for _, m := range s.pkgB.mods {
		if m.std || m.tree == nil || m.tree.osRoot == "" {
			continue
		}
		path := filepath.Join(m.tree.osRoot, filepath.FromSlash(m.dir), "gen", target, "gen.mk")
		have, err := os.ReadFile(path)
		exists := err == nil
		var f *source.File
		if m.gen != nil && m.gen.out != nil {
			f = m.gen.out.File
		}
		if f == nil && m.fromCache {
			// A module hit's generated file, rebuilt from the cache
			// (GenRef, genref.go).
			f, _ = s.w.sm.ByPath(genVirtualPath(s.w, m))
		}
		if f == nil {
			// Removed only once the module has no gen line at all: a
			// module whose stage 3 failed, or whose generators failed,
			// keeps the last view, which is what one debugging them reads.
			if exists && m.noGenLines() && genViewOwned(have) {
				_ = os.Remove(path)
			}
			continue
		}
		want := genViewBytes(f.Text, target)
		switch {
		case exists && string(have) == string(want):
		case exists && !genViewOwned(have):
			out = append(out, e0904(f, m.path))
		default:
			writeGenView(path, want)
		}
	}
	return out
}

// e0904 is the hand-edited view of module, cited at line 1, column 1 of the
// generated file, whose path is the view's.
func e0904(f *source.File, module string) *diag.Diagnostic {
	return diag.New(diag.E0904, source.Span{File: f.ID}, "`"+f.Path+"` was edited by hand: it is a view mk writes "+
		"from the module's gen lines, and the compiler does not read it").
		Text("view", f.Path).Text("module", module).
		Alt("delete " + f.Path + ": the next mk command writes it again from the gen lines").
		Alt("make the change in the generator or in the gen line's arguments")
}

// writeGenView writes data to path through a temporary file in the same
// directory and a rename, so a reader (or a second mk) never sees half a
// view.
func writeGenView(path string, data []byte) {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return
	}
	tmp, err := os.CreateTemp(dir, ".gen-*.tmp")
	if err != nil {
		return
	}
	_, werr := tmp.Write(data)
	cerr := tmp.Close()
	if werr != nil || cerr != nil || os.Rename(tmp.Name(), path) != nil {
		_ = os.Remove(tmp.Name())
	}
}
